using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text.Json;
using NorthStar.Combat;
static class Program {
 static int count;static void C(string id,bool ok){if(!ok)throw new Exception("FAIL "+id);count++;Console.WriteLine("PASS "+id);}static void Reject(string id,Action a){try{a();}catch(ArgumentException){C(id,true);return;}catch(OverflowException){C(id,true);return;}throw new Exception("No rejection "+id);}
 static int Main(string[] args){try{if(args.Length==3&&args[0]=="--vectors")return Vectors(args[1],args[2]);if(args.Length!=0)throw new Exception("Expected --vectors INPUT OUTPUT or no arguments");
 C("tiny-positive-hit",Formula.Hit(0.0000001,0,1,1)==0.9);C("tiny-positive-apply",Formula.ApplyChance(0.0000001,0)==0.95);C("hit",Formula.Hit(50,50,10,10)==0.45);C("hit-floor",Formula.Hit(0,0,0,0)==0.05);C("hit-cap",Formula.Hit(100,0,1000,0)==0.95);C("crit",Formula.Crit(100)==0.5);C("raw",Formula.Raw(120,0.8,0.25)==120);C("mitigation",Formula.Mitigate(100,200,10)==50);C("round-away",Formula.Mitigate(5,100,0)==3);C("apply-floor",Formula.ApplyChance(0,0)==0.05);C("duration-away",Formula.Duration(3,50,0)==5);C("duration-floor",Formula.Duration(3,0,200)==1);C("reapply-zero",Formula.Reapply(0,0)==1);C("unknown-dot",Formula.Dot("FROST",100)==0);C("dot-no-trim",Formula.Dot(" POISON",100)==0);C("dot-case",Formula.Dot("poison",100)==6);C("minHP-zero",Formula.Dot("POISON",1)==0);C("dot-away",Formula.Dot("BLEED",50)==2);
 Reject("nan",()=>Formula.Hit(double.NaN,1,1,1));Reject("infinity",()=>Formula.Raw(1,double.PositiveInfinity,0));Reject("negative",()=>Formula.ApplyChance(-1,2));Reject("level",()=>Formula.Mitigate(2,1,-1));Reject("sum-overflow",()=>Formula.Reapply(int.MaxValue,1));
 var e=new EffectSet();e.Apply(Effect.Poison,2);e.Apply(Effect.Poison,3);C("add-not-max",e.Remaining(Effect.Poison)==5);e.Apply(Effect.Bleed,1);e.Apply(Effect.Burn,1);e.Apply(Effect.Disarm,1);C("modifiers",e.AttackMultiplier==0.7&&e.HealingMultiplier==0.7&&!e.WeaponEnabled);var v=e.Snapshot();v[0]=null!;C("snapshot-copy",e.Snapshot()[0]!=null);Reject("enum",()=>e.Apply((Effect)99,1));Reject("zero-duration",()=>e.Apply(Effect.Burn,0));Reject("cap-atomic",()=>e.Apply(Effect.Poison,996));C("cap-unchanged",e.Remaining(Effect.Poison)==5);Reject("skip-round",()=>e.EndRound(2,100));Reject("HP-atomic",()=>e.EndRound(1,-1));C("invalid-unchanged",e.Remaining(Effect.Bleed)==1);var t=e.EndRound(1,100);C("global-dot-sum",t.Damage==12);C("all-entry",t.Entries.Length==4);C("decrement-once",e.Remaining(Effect.Poison)==4);C("expiry",e.Remaining(Effect.Bleed)==0&&e.AttackMultiplier==1&&e.HealingMultiplier==1&&e.WeaponEnabled);Reject("duplicate",()=>e.EndRound(1,100));C("duplicate-unchanged",e.Remaining(Effect.Poison)==4);var entries=t.Entries;entries[0]=null!;C("tick-copy",t.Entries[0]!=null);C("cleanse-count",e.Cleanse()==1);C("cleanse-empty",e.Cleanse()==0);C("empty-round",e.EndRound(2,100).Damage==0);Console.WriteLine($"{count} native controls passed");return 0;
 }catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
 static int Vectors(string input,string output){using var doc=JsonDocument.Parse(File.ReadAllText(input));var results=new List<object>();bool all=true;foreach(var vector in doc.RootElement.GetProperty("vectors").EnumerateArray()){string component=vector.GetProperty("component").GetString()??throw new Exception("Missing component");var row=vector.GetProperty("row");string S(string k)=>row.GetProperty(k).GetString()??throw new Exception("Missing "+k);double N(string k){double n=double.Parse(S(k),NumberStyles.Float,CultureInfo.InvariantCulture);if(!double.IsFinite(n))throw new Exception("Nonfinite "+k);return n;}int I(string k)=>int.Parse(S(k),NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture);double actual;string key;
 switch(component){case "HIT":actual=Formula.Hit(N("ACC"),N("EVA"),I("LvlAtk"),I("LvlDef"),N("BaseHitSkill"));key="Expected_HitChance";break;case "CRIT":actual=Formula.Crit(N("CRIT_percent"),N("CritBaseSkill"));key="Expected_CritChance";break;case "RAW":actual=Formula.Raw(N("ATK_or_MATK"),N("EscalaCoef"),N("Letalidade"));key="Expected_RawDamage";break;case "MIT":actual=Formula.Mitigate(N("RawDamage"),N("DEF_or_MDEF"),I("LvlDef"));key="Expected_MitigatedDamage";break;case "APPLY":actual=Formula.ApplyChance(N("EFF"),N("RES"),N("BaseApplySkill"));key="Expected_ApplyChance";break;case "DUR":actual=Formula.Duration(N("BaseDur"),N("DurApply_percent"),N("Ten_percent"));key="Expected_Duration";break;case "DOT":actual=Formula.Dot(S("StatusID"),I("HPmax"));key="Expected_DOT_Tick";break;case "REAPPLY":actual=Formula.Reapply(I("Remaining"),I("Add"));key="Expected_NewRemaining";break;case "FINAL_DAMAGE":int flag=I("DefenderFlag");if(flag!=0&&flag!=1)throw new Exception("Invalid DefenderFlag");int d=Formula.Mitigate(Formula.Raw(N("ATK_or_MATK"),N("EscalaCoef"),N("Letalidade")),N("DEF_or_MDEF"),I("LvlDef"));actual=flag==1?Math.Round(d*0.5,MidpointRounding.AwayFromZero):d;key="Expected_FinalDamage";break;default:throw new Exception("Unknown component "+component);}
 double expected=N(key);bool passed=Math.Abs(expected-actual)<=(component=="RAW"?1e-5:1e-6);all&=passed;results.Add(new {component,id=S("TestID"),expected,actual,passed});}if(results.Count==0)throw new Exception("Empty vectors");File.WriteAllText(output,JsonSerializer.Serialize(new {vectors=results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"{results.Count} historical vectors; all passed: {all}");return all?0:1;}
}
